sys_script_include.script:
var CustomScriptInclude = Class.create();
CustomScriptInclude.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    updatePropertyValue: function() {
        var property = this.getParameter('sysparm_property');
        var suggestedValue = this.getParameter('sysparm_suggested_value');

        try {
            // Perform the server-side update of the property here
            var gr = new GlideRecord('sys_properties'); // Or the appropriate table
            gr.get('name', property); // Or use sys_id if you are passing that
            if (gr.isValid()) {
                gr.setValue('value', suggestedValue);
                gr.update();
                return 'success'; // Return 'success' on successful update
            } else {
                gs.error("Property not found: " + property);
                return 'error';
            }
        } catch (ex) {
            gs.error("Error updating property: " + ex);
            return 'error';
        }
    },

    type: 'CustomScriptInclude'
});
